import{_ as e,o,c as d,a2 as r}from"./chunks/framework.il0noOp3.js";const h=JSON.parse(`{"title":"Microsoft Assessment Coverage","description":"Every assessment in Microsoft's assessment catalog, and the Scout assessment that runs it.","frontmatter":{"description":"Every assessment in Microsoft's assessment catalog, and the Scout assessment that runs it."},"headers":[],"relativePath":"reference/microsoft-assessment-coverage.md","filePath":"reference/microsoft-assessment-coverage.md"}`),s={name:"reference/microsoft-assessment-coverage.md"};function a(i,t,c,n,l,A){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="microsoft-assessment-coverage" tabindex="-1">Microsoft Assessment Coverage <a class="header-anchor" href="#microsoft-assessment-coverage" aria-label="Permalink to &quot;Microsoft Assessment Coverage&quot;">​</a></h1><p>Microsoft publishes its self-assessments at <a href="https://learn.microsoft.com/assessments/browse/" target="_blank" rel="noreferrer">learn.microsoft.com/assessments</a>. This page maps each one to the Scout assessment that runs it. It was checked against the catalog on 2026-11-25.</p><p>Two things are true of almost all of them:</p><ul><li><strong>Microsoft publishes no question text.</strong> The assessments are interactive questionnaires behind sign-in. Scout&#39;s items are its own reading of the guidance each assessment is built on, and each framework page says so.</li><li><strong>Many questions are about how an organisation works</strong>, not how a resource is configured. Scout answers what Azure data can answer, attaches the evidence it has, and takes the rest as <a href="./../assessment/questionnaire-answers.html">questionnaire answers</a>.</li></ul><h2 id="azure-assessments" tabindex="-1">Azure assessments <a class="header-anchor" href="#azure-assessments" aria-label="Permalink to &quot;Azure assessments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Microsoft assessment</th><th>Scout assessment</th><th>Notes</th></tr></thead><tbody><tr><td>Azure Well-Architected Review</td><td><code>WAF: Reliability</code>, <code>WAF: Security</code>, <code>WAF: Cost Optimization</code>, <code>WAF: Operational Excellence</code>, <code>WAF: Performance Efficiency</code>, <code>CAF: Azure Landing Zone</code></td><td>Core review, by pillar</td></tr><tr><td>Azure Well-Architected Framework Maturity Model Assessment</td><td><code>WAF: Maturity Model</code></td><td></td></tr><tr><td>Well-Architected service guides (guidance, not in the catalog)</td><td><code>WAF: Service Guides</code></td><td>Configuration recommendations of 20 service guides</td></tr><tr><td>Azure Landing Zone Review</td><td><code>CAF: Azure Landing Zone</code> and the eight <code>CAF:</code> design areas</td><td></td></tr><tr><td>Azure Local | Well-Architected Review</td><td><code>WAF: Azure Local</code></td><td></td></tr><tr><td>Azure Well-Architected AI workload</td><td><code>Assess: AI Workload</code></td><td>All ten design areas</td></tr><tr><td>Azure Well-Architected Azure Virtual Desktop workload</td><td><code>Workload: AVD</code> (AVD in Azure), <code>Assess: AVD Workload</code> (AVD on Azure Local)</td><td></td></tr><tr><td>Azure Well-Architected Azure VMware Solution workload</td><td><code>Workload: AVS</code></td><td></td></tr><tr><td>Azure VMware Solution Landing Zone Assessment Review</td><td><code>Workload: AVS Landing Zone</code></td><td></td></tr><tr><td>Azure Well-Architected Oracle on Azure IaaS workload</td><td><code>Workload: Oracle on Azure IaaS</code></td><td>Automated checks cover VMs from Oracle Marketplace images</td></tr><tr><td>Azure Well-Architected SaaS workload</td><td><code>Workload: SaaS</code></td><td></td></tr><tr><td>SAP on Azure | Well-Architected Review</td><td><code>Workload: SAP on Azure</code></td><td>Automated checks cover SAP registered with Azure Center for SAP solutions</td></tr><tr><td>Mission Critical | Well-Architected Review</td><td><code>WAF: Mission Critical</code></td><td></td></tr><tr><td>Sustainability | Well-Architected Review</td><td><code>WAF: Sustainability</code></td><td></td></tr><tr><td>Go-Live | Well-Architected Review</td><td><code>WAF: Go-Live</code></td><td>Microsoft publishes only a landing page; Scout&#39;s is its own production-readiness review</td></tr><tr><td>Azure Machine Learning</td><td><code>WAF: Azure Machine Learning</code></td><td></td></tr><tr><td>Azure AI Search (Well-Architected)</td><td><code>WAF: Azure AI Search</code></td><td></td></tr><tr><td>Analytics (Well-Architected)</td><td><code>WAF: Analytics</code></td><td></td></tr><tr><td>Data Services (Well-Architected)</td><td><code>WAF: Data Services</code></td><td></td></tr><tr><td>Cloud Adoption Security Assessment (CASA)</td><td><code>Microsoft: CASA</code></td><td></td></tr><tr><td>DevOps Capability Assessment</td><td><code>Microsoft: DevOps Capability</code></td><td></td></tr><tr><td>FinOps Review (New)</td><td><code>Microsoft: FinOps Review</code></td><td>FinOps Framework 2026</td></tr><tr><td>AI Readiness Assessment</td><td><code>Microsoft: AI Readiness</code></td><td></td></tr><tr><td>Technical Assessment for Generative AI in Azure</td><td><code>Microsoft: Generative AI Technical</code></td><td></td></tr><tr><td>GenAIOps Maturity Model Assessment</td><td><code>Microsoft: GenAIOps Maturity</code></td><td></td></tr><tr><td>Platform Engineering Technical Assessment</td><td><code>Microsoft: Platform Engineering</code></td><td></td></tr><tr><td>Analytics Journey Tracker</td><td><code>Microsoft: Analytics Journey Tracker</code></td><td></td></tr><tr><td>App and Data Modernization Readiness Tool</td><td><code>Microsoft: App and Data Modernization</code></td><td></td></tr><tr><td>Well-Architected Reliability Assessment (WARA tooling, not in the catalog)</td><td><code>Microsoft: Well-Architected Reliability Assessment</code></td><td>Backed by the Azure Proactive Resiliency Library</td></tr><tr><td>Azure Advisor (not in the catalog)</td><td><code>Microsoft: Azure Advisor</code></td><td></td></tr><tr><td>Regulatory compliance in Azure Policy (not in the catalog)</td><td><code>Assess: Compliance</code></td><td>Every assigned initiative: MCSB, CIS, ISO 27001, NIST, PCI DSS and more</td></tr></tbody></table><h2 id="retired-by-microsoft" tabindex="-1">Retired by Microsoft <a class="header-anchor" href="#retired-by-microsoft" aria-label="Permalink to &quot;Retired by Microsoft&quot;">​</a></h2><p>Microsoft deletes these in January 2027. Scout keeps the capability, re-based on the guidance each was built on, and the old names still work.</p><table tabindex="0"><thead><tr><th>Microsoft assessment</th><th>Scout assessment</th></tr></thead><tbody><tr><td>Strategic Migration Assessment and Readiness Tool (SMART)</td><td><code>CAF: Migrate readiness</code> (CAF Plan + CAF Migrate)</td></tr><tr><td>Cloud Governance</td><td><code>CAF: Govern</code> (CAF Govern)</td></tr><tr><td>Cloud Journey Tracker, Cloud Adoption Strategy Evaluator, Developer Velocity Assessment</td><td>Not carried forward: Microsoft retired them without a replacement methodology</td></tr></tbody></table><h2 id="microsoft-products-other-than-azure" tabindex="-1">Microsoft products other than Azure <a class="header-anchor" href="#microsoft-products-other-than-azure" aria-label="Permalink to &quot;Microsoft products other than Azure&quot;">​</a></h2><p>Scout runs these as questionnaires: it does not read Power Platform, Microsoft 365, Dataverse or client-device data yet, so every item is answered with <a href="./../assessment/questionnaire-answers.html">questionnaire answers</a>. Each framework page names the Microsoft APIs an automated version would need.</p><table tabindex="0"><thead><tr><th>Microsoft assessment</th><th>Scout assessment</th><th>Notes</th></tr></thead><tbody><tr><td>Power Platform Well-Architected</td><td><code>Microsoft: Power Platform Well-Architected</code></td><td>Microsoft&#39;s checklist codes (RE:01 ...)</td></tr><tr><td>Power Platform Solution Assessment</td><td><code>Microsoft: Power Platform Solution</code></td><td></td></tr><tr><td>Power Platform Adoption Assessment</td><td><code>Microsoft: Power Platform Adoption</code></td><td></td></tr><tr><td>Data Security for Copilot for Microsoft 365</td><td><code>Microsoft: M365 Copilot Data Security</code></td><td>Product now Microsoft 365 Copilot</td></tr><tr><td>Microsoft Sustainability Manager | Well-Architected Assessment</td><td><code>Microsoft: Sustainability Manager Well-Architected</code></td><td>Product now Dynamics 365 Sustainability</td></tr><tr><td>Microsoft Cloud for Financial Services | Well-Architected for Industry</td><td><code>Microsoft: Cloud for Financial Services Well-Architected</code></td><td>Product now Microsoft for Financial Services</td></tr><tr><td>Windows 11 Pro Migration Readiness Assessment</td><td><code>Microsoft: Windows 11 Migration Readiness</code></td><td>Windows 10 reached end of support on 2025-10-14</td></tr></tbody></table><p>The catalog&#39;s partner journeys (Microsoft Partner and industry readiness guides) and learner skill self-assessments are training material, not assessments of an environment, so Scout does not run them.</p>',13)])])}const m=e(s,[["render",a]]);export{h as __pageData,m as default};
